parts.append(section('2　版本、输入与归档溯源',table(['组成','版本／完整提交哈希','说明'],[[e(x) for x in r] for r in versions])+p('正式工具 ZIP SHA-256：'+code('b00ad41c841f85e66767852604e1ac46c48b2ed0d9e29faf2ccfb91db316621f')+'；二进制 SHA-256：'+code('63eaf07f9ee1d0f3f7f1c7a4bb9507455343f5ad2d4bb37b40c584904a94e932')+'；启动脚本 SHA-256：'+code('dde429fe0347ae2ed77d03bc3cf34b50e5f21f8ace6933d1eac554ed95b5ec73')+'。')+p('二进制报告 CBMC 5.67.0（POPL26-exp-8-ga6ad3e6a8-dirty）。这不是可证明的干净源码构建标识；本报告仅确认官方二进制和对应版本附近源码的关系，不声称已从某个干净提交重建出完全相同二进制。最新仓库 HEAD 980fe9e6757e967d12454c7d16e2ec4de1a1cae4 仅作为获取时状态记录，实际分析使用比赛更新提交。')+p('逐个比对 8 份主赛道 raw／fixed XML，用户仓库与官方 results-verified 归档语义完全一致。667 个执行实例的 YAML、输入和属性共 2,001 项哈希校验全部匹配比赛 fileHashes。基准归档另外提取 1,043 个相关文件，与固定 Git 提交逐字节一致。预处理 .i 输入直接使用归档原件；没有以当前最新版基准替代。')+p('大型 ZIP 使用 HTTP Range 读取目录和选定成员：已校验被提取成员 CRC，witness 另校验 SHA-256。没有完整下载 29 GB 结果 ZIP 或 15 GB witness ZIP，因此不声称已校验这些完整 ZIP 的总 MD5。归档元数据、成员偏移和校验清单均保存。')+p('官方页面与归档：<a href="https://sv-comp.sosy-lab.org/2026/systems.php">参赛系统</a>；<a href="https://zenodo.org/records/17636587">Deagle 工具包</a>；<a href="https://zenodo.org/records/19736446">结果归档</a>；<a href="https://zenodo.org/records/18650775">基准归档</a>；<a href="https://zenodo.org/records/18651735">witness 归档</a>；<a href="https://zenodo.org/records/18653053">验证器日志归档</a>。')))
parts.append(section('3　执行环境、资源限制与排除记录',p('用户服务器为 Ubuntu 22.04.5、Linux 5.15.0-186、KVM AMD 通用处理器，32 个逻辑 CPU（16 核 × 2 SMT）、约 130.7 GB 物理内存、无 swap。官方记录为 Intel Xeon E3-1230 v5、8 个逻辑 CPU、Linux 6.8.0-88；硬件与内核无法完全相同，耗时比较不视为精确性能复现。')+p('正式二进制需要服务器原生环境没有的较新 GLIBC／GLIBCXX。运行在专用目录内的 Ubuntu 24.04.3 base 隔离根文件系统，补入固定 noble release 软件包：Python 3.12.3、GCC 13.2.0-23ubuntu4、完整 gcc-multilib 开发头文件。未升级服务器系统包。实际库版本、包版本及 SHA-256 见 provenance 和 packages-manifest。')+table(['限制／隔离','实际设置'],[['单任务 CPU','900 秒 soft；960 秒 hard（官方 deagle.xml 的硬上限后备设置）'],['单任务内存','15,000,000,000 字节；内核页对齐后 memory.max=14,999,998,464；swap=0'],['并行','7 组，每组 4 个互不重叠逻辑 CPU：4–7、8–11、…、28–31'],['管理与诊断','CPU 0–3；诊断独立 cgroup，不附加或中断基线进程'],['目录','全部位于 /root/deagle-svcomp26-repro-20261021-01a15ee7'],['工具命令','./deagle PROPERTY INPUT --32；所有选中实例均为 ILP32']])+p('用 BenchExec 3.32 RunExecutor 限制整个进程组，包含启动脚本及其子进程。官方年度复现说明提到 3.34，但该 Deagle 原始 XML 明确记录 3.32，因此没有静默替换。CPU 时间不是 wall time；脚本内部的 timeout 5 使用 wall time，会受硬件速度影响。')+p('<b>内存峰值限制：</b>Linux 5.15 没有 cgroup memory.peak。每约 20 ms 采样 memory.current，记录“采样峰值下界”，并另存 wait4 返回的 ru_maxrss；它可能遗漏清理时被重新托管的子进程，也不是整个进程树的可靠最大值。两者都不能冒充精确进程组峰值。每约 0.5 秒保存进程、CPU、RSS、cgroup 内存和日志尾部。内存上限仍由内核实际执行。')+p('启动脚本重定向并可能删除内部日志，外层 stdout／stderr 完整保存；观察器打开临时文件并在删除后继续读取。极短暂文件可能在观察器首次打开前消失，不能保证所有临时字节均被截获。关键 UNKNOWN 均取得实际错误日志，并对代表实例直接调用原二进制参数补充完整诊断。')+p('环境试运行曾发现缺少 gnu/stubs-x32.h 时 GCC 预处理失败，而 Deagle 继续运行并可能报告空洞 TRUE。相关试运行全部移入 evidence/environment-missing-x32-runs，明确排除，不计入 667 次有效运行。补齐 multilib 后重新执行全部任务，保留失败环境记录供审计。初始临时目录错误的 smoke 也单独保存。')))
