if byid.get('de84c5202513fc9b',{}).get('completed'):
 parts.append(section('资源诊断：约束构造与求解图',p('对 5762debd1f9e9bfe（09-regions_21-arrayloop2_nr／no-overflow），独立最终参数运行在 390 秒处的 GDB 栈为 merge_irept::merged、register_read_from_choice_symbol、memory_model_baset::read_from、memory_model_sct::operator()。基线约 484.18 CPU 秒在 SC 构造阶段触及 15 GB；日志包含 1,692,474 个表达式步骤，部分堆节点有 5,472 次读和 20 次写。栈与规模支持 read-from 约束构造的定位，但不是终止瞬间的精确内存分配剖析。')+p('对 160c74f546f52fb0（elimination_backoff_stack／no-overflow），60 秒诊断栈为 Minisat::closure::get_node、ClosureSolver::set_graph。其基线之后完成图构造和后处理，再于约 219.80 CPU 秒发生 OOM。因此，该中途栈不能当作 OOM 瞬间栈；阶段资源曲线与终止前日志另存。程序只有有限次 push/pop，仍产生 851,459 个表达式步骤，说明“循环少”不等于并发／别名公式小。')+p('完整栈及行号在逐实例 JSON 的 diagnostic_stack_evidence；所有额外诊断均未修改输入、属性或 Deagle 核心语义。')))
 a=byid['de84c5202513fc9b'];m=a['final_phase_metrics'];re=a.get('resource_evidence',{})
 parts.append(section('资源典型案例：链表与大量竞争候选',p('goblint-regression/09-regions_21-arrayloop2_nr 的 no-data-race 实例 '+code(a['id'])+'：程序初始化 10 个槽位、每槽 30 个堆节点，两个线程遍历带锁链表。日志中的表达式步骤数为 '+num(m.get('max_expression_steps'),0)+'，过滤后竞争候选对数 '+num(m.get('races_after_filter'),0)+'，竞争类别 '+num(m.get('race_categories_after_filter'),0)+'。终止前尚未出现完成 Runtime Symex 或进入 SAT 的证据。')+p('采样阶段时间：'+e(json.dumps(re.get('phase_wall_seconds_observation_estimate',{}),ensure_ascii=False))+'。此处 Runtime Symex 的内部计时范围包含展开后的性质处理，不能仅凭计时名称把所有耗时称作循环展开。候选数量和程序结构支持“表示／性质编码规模很大”的判断；不能据此给出无限资源下必然可解的结论。')+excerpt(a,['steps before removal','number of races','number of race categories'],5)))
parts.append(section('9　四个错误验证结果的单独核查',table(['任务','官方期望','复现工具报告','已得到的直接证据／边界'],[['pthread-theta/unwind1-100','false / unreach-call','true','未知循环使用 3；102 展开诊断给出 reach_error 反例'],['pthread-theta/unwind2-100','false / unreach-call','true','同上；共享 limit 与线程交错导致原断言可违反'],['pthread-complex/workstealqueue_mutex-2','true / unreach-call','false(unreach-call)','保留完整 trace；SyncPush 展开完整性检查失败；精确 false-positive 根因未确认'],['pthread-memsafety/list1','false / valid-deref','true','68 VCC、简化后剩余 0；线程 create/join 被折叠，pthread_exit 终止当前路径；期望 valid-deref 对应的精确漏报根因未确认']])+p('两个 theta 诊断先尝试 101，再对所有循环使用 102 并开启 --unwinding-assertions 和 --trace。unwind1 的 101 结果只是新增展开断言失败，不能当作原 reach_error 反例；102 的失败明确对应原性质，才构成所述证据。诊断成功不计入原参数结果。')+p('workstealqueue 的文本 trace 中出现 thread 2 的 Operation 在其打印的初始化事件之前，说明输出执行顺序需要独立核验；这不足以单独确定是公式、模型、trace 序列化还是其他环节的问题。原参数包含 --refined-pointer-analysis，源码将其与 allow-pointer-unsoundness 关联，但没有因果对照支持把这一选项直接定为该实例根因。')+p('list1 的 verbosity 10 和 --show-vcc 诊断明确显示 create/join 被替换为 build／delete 的普通函数调用，build 以 thread 0 执行，在 pthread_exit 的 assume(false) 处截断；没有剩余 VCC，因而不能把该 TRUE 解释为充分的 SAT 证明。该现象与原任务预期的 valid-deref 漏报之间的精确因果链尚未闭合。没有修改 malloc、内存模型、程序或属性来强行取得结论。')))
parts.append(section('10　跨属性分析与策略可改善性',p('同一程序的异常不是独立根因的简单累加：goblint-regression 的大量跨属性 ERROR 由同一 300 阈值产生；libvsync 与 ldv-linux-3.14-races 的跨属性 UNKNOWN 由相同 asm 前端限制产生。bounded_buffer 在内存安全属性触发 value_set 不变式，而其他属性可能耗尽内存；属性插桩会改变符号状态与公式，不能把一个属性的异常原因自动复制到另一个属性。program-cross-property.json 给出 346 个 YAML 的逐属性映射。')+table(['情况','保持原算法时的策略判断','证据强度'],[['两个 theta 错误 TRUE','展开策略改变已找到原性质反例；应保留完整性检查，不能把有限展开通过当无界证明','直接诊断，高'],['248 次阈值 ERROR','提高阈值可避免立即放弃，但未证明能在 900 秒／15 GB 内完成；单纯延长时间无效','退出分支，高；完成能力未确认'],['35 TIMEOUT、25 OOM','可研究时间分配、首次尝试和展开策略；不能从资源终止推断必然改善，增大展开还可能增加内存','逐例日志／资源证据；可改善性未确认'],['asm、TLS、不变式','增加运行时间无依据；需要能力／实现变化，超出本阶段','直接错误，高'],['witness 缺失／空字段','增加求解时间不会改变显式跳过或序列化错误；需要输出／验证环节变化','代码与文件，高'],['19 unconfirmed','按各验证器实际超时、异常、拒绝、投票冲突区分；没有统一加时可解决的依据','状态高，语义根因不确定'],['其余两个错误结果','已重现；没有证据证明加时可纠正','根因未确认']])+p('本阶段未修复工具、修改核心算法、改写待验证程序或属性。报告中“实现错误或环境问题”“固定启发式导致提前放弃”“计算资源不足”“当前验证算法能力限制”“witness 生成或验证问题”“尚未确定原因”互斥计数，但证据还保留各层问题可能同时存在的事实。')))
parts.append(section('11　交付文件与重新执行',p('完整复现包解压后包含 sources、runtime、scripts、reports、runs、diagnostics、archives 和 evidence。每个 runs/ID 保存 command.json、reproduce-command.sh、stdout.log、stderr.log、result.json、observations.jsonl、捕获的内部日志，以及实际生成的 witness。未生成的文件不会伪造为“存在”。资源任务另有 resource-timeline.csv。')+p('在原服务器专用目录运行 '+code('bash scripts/reexecute.sh')+' 可在新的 replays/ 时间戳目录重跑全部任务；'+code('bash scripts/reexecute.sh 15fbf61018a5dd49')+' 可按 ID 重跑单例。脚本要求 root、cgroup v2、至少 32 个逻辑 CPU，复制隔离环境并通过同一资源执行器运行，不覆盖已有结果。单例目录的 reproduce-command.sh 只是完整工具调用记录，本身不施加资源上限；正式复跑应使用 reexecute.sh。')+p('完整提交、软件包版本、脚本 SHA-256、输入和 witness 哈希可在 provenance.json、script-version.json、SHA256SUMS 与各 command.json 中核查。下载包中不含服务器登录密码。')))
